var SEVENMMTV_REMOTE_B64_URL = 'https://raw.githubusercontent.com/xiaoxiaoxia136/master/main/Hiker/%F0%9D%9F%95%F0%9D%90%8C%F0%9D%90%8C%F0%9D%90%93%F0%9D%90%95.js';
var SEVENMMTV_LOCAL_FILE = 'hiker://files/rules/Apollo/𝟕𝐌𝐌𝐓𝐕.js';
function SevenMMTV_decodeRemote(raw) {
    raw = String(raw || '').replace(/^\uFEFF/, '').trim();
    if (raw.indexOf('Apollo') >= 0 && raw.indexOf('$.exports') >= 0) return raw;
    raw = raw.replace(/[\r\n\t\s]/g, '');
    return base64Decode(raw);
}
function SevenMMTV_updateRemote() {
    try {
        var old = '';
        try { old = fetch(SEVENMMTV_LOCAL_FILE) || ''; } catch(e0) {}
        var remote = fetch(SEVENMMTV_REMOTE_B64_URL, { timeout: 15000 });
        var code = SevenMMTV_decodeRemote(remote);
        if (!code || code.indexOf('Apollo') < 0 || code.indexOf('$.exports') < 0) throw new Error('远程文件内容异常');
        if (old !== code) {
            writeFile(SEVENMMTV_LOCAL_FILE, code);
            var ver = (code.match(/version\s*:\s*["']([^"']+)/) || [])[1] || '2026061401';
            var msg = '远程已更新:' + ver;
            try { toast(msg); } catch(e1) { log(msg); }
        }
    } catch(e) {
        log('7MMTV远程更新失败：' + e.message);
    }
}
SevenMMTV_updateRemote();

