    maskText: function(v) {
        if (v == null) return '';
        let s = String(v);
        // 与“替换违禁词导入”相同原理：命中词内部插入零宽字符。
        // 仅作用于界面显示文本，API、ID、URL、搜索参数保持原值。
        let p = decodeURIComponent('%E6%80%A7%E7%98%BE|S%E7%BA%A7|%E5%81%B7%E6%8B%8D|%E6%97%A0%E7%A0%81|%E6%9C%89%E7%A0%81|%E5%8F%A3%E7%88%86|%E4%BC%A6%E7%90%86|%E5%95%AA%E5%95%AA|%E7%BA%A6%E7%82%AE|%E5%B0%91%E5%A6%87|%E7%BF%98%E8%87%80|%E5%91%BB%E5%90%9F|%E5%8F%8C%E9%A3%9E|%E5%A7%BF%E5%8A%BF|%E6%83%85%E8%89%B2|%E5%A5%B3%E4%BC%98|%E4%BA%BA%E5%A6%BB|%E6%80%A7%E7%88%B1|%E4%B9%B1%E4%BC%A6|%E5%BC%BA%E5%A5%B8|%E6%AF%8D%E7%8B%97|%E5%AA%9A%E9%BB%91|%E7%99%BD%E8%99%8E|%E7%86%9F%E5%A5%B3|%E7%BD%91%E9%BB%84|%E8%B0%83%E6%95%99|%E8%87%AA%E6%85%B0|%E5%8F%A3%E4%BA%A4|%E6%80%A7%E4%BA%A4|%E7%BE%A4%E4%BA%A4|%E5%86%85%E5%B0%84|%E9%A2%9C%E5%B0%84|%E6%BD%AE%E5%90%B9|%E4%B9%B3%E4%BA%A4|%E8%82%9B%E4%BA%A4|S​M|%E8%90%9D%E8%8E%89');
        try {
            return s.replace(new RegExp(p, 'g'), function(m) {
                return Array.from(m).join('\u200B');
            });
        } catch (e) {
            return s;
        }
    },
    cleanText: function(v) {
        if (v == null) return '';
        let s = String(v).replace(/<[^>]+>/g, '').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/\\n/g, '\n').replace(/[ \t]+/g, ' ').trim();
        return this.maskText(s);
    },
    episodeName: function(e, idx, seriesTitle) {
        e = e || {};
        let no = e.episodeNo != null ? parseInt(e.episodeNo) : (idx + 1);
        if (!(no > 0)) no = idx + 1;
        let t = this.cleanText(e.title || e.name || '');
        let st = this.cleanText(seriesTitle || '');
        // 源站很多短剧把每一集 title 都返回成整部剧名，二级页会出现 96 个完全相同按钮。
        // 只有标题与剧名明显不同且足够短时才保留集标题，否则统一使用“第N集”。
        if (t && t !== st && t.indexOf(st) !== 0 && t.length <= 18) return '第' + no + '集 · ' + t;
        return '第' + no + '集';
    },
    detail: function() {
        let d = this.d = [];
        let id = MY_PARAMS.mdai_id || '';
        let type = MY_PARAMS.mdai_type || 'video';
        let fallbackTitle = MY_PARAMS.mdai_title || '';
        try {
            if(type=='post'){
                let x=this.payload(this.request('/api/v1/posts/'+encodeURIComponent(id)))||{};
                let title=this.cleanText(x.title||fallbackTitle||'帖子详情');setPageTitle(this.shortTitle(title,16));
                let cover=this.image(x.coverUrl||''),meta=[];if(x.categoryName)meta.push(this.cleanText(x.categoryName));if(x.viewCount!=null)meta.push('👀'+this.compactNum(x.viewCount));if(x.likeCount!=null)meta.push('❤'+this.compactNum(x.likeCount));if(x.publishedAt)meta.push(this.fmtDate(x.publishedAt).slice(0,10));
                let localInfo={id:String(id),type:'post',title:title,cover:cover,desc:meta.join(' · ')};this.saveHistory(localInfo);
                // 系统标题栏已显示标题；正文区只保留紧凑信息条，避免长标题重复占两屏。
                if(meta.length)d.push({title:'““””<small><font color=#858592>'+meta.join(' · ')+'</font></small>',url:'hiker://empty',col_type:'rich_text',extra:{lineVisible:false}});
                let favNow=this.isFav(id,'post');
                d.push({title:favNow?'❤ 已收藏':'♡ 收藏',url:$('#noLoading#').lazyRule((info)=>{let on=$.require('mdai').toggleFav(info);refreshPage(false);return 'toast://'+(on?'已加入收藏':'已取消收藏');},localInfo),col_type:'scroll_button',extra:{backgroundColor:favNow?'#207C6CFF':'#0A777785',lineVisible:false}});
                let content=this.cleanText(x.content||'');
                if(content){d.push({col_type:'blank_block'});d.push({title:content,url:'hiker://empty',col_type:'long_text',extra:{lineVisible:false}});}
                let imgs=Array.isArray(x.images)?x.images:[];
                if(!imgs.length && cover) imgs=[x.coverUrl];
                if(imgs.length){
                    d.push({col_type:'blank_block'});
                    imgs.forEach((u)=>{
                        let iu=this.image(u);
                        if(iu)d.push({pic_url:iu,img:iu,url:iu+'#.jpg#',col_type:'pic_1_full',extra:{lineVisible:false}});
                    });
                }
                if(x.videoUrl){d.push({col_type:'blank_block'});d.push({title:'▶ 播放帖子视频',url:$('#noLoading#').lazyRule((u)=>$.require('mdai').play(u),x.videoUrl),col_type:'text_center_1',extra:{lineVisible:false}});}
                d.push({col_type:'blank_block'});
                d.push({title:'💬 评论区',desc:'查看全部评论',url:this.commentsUrl('post',id,title),col_type:'text_1',extra:{lineVisible:false}});
                setResult(d);return;
            }
            let path = type == 'drama' ? '/api/v1/short-dramas/' + encodeURIComponent(id) + '?productId=1' : '/api/v1/videos/' + encodeURIComponent(id);
            let obj = this.request(path);
            let x = this.payload(obj) || {};
            let title = this.cleanText(x.title || fallbackTitle || '详情');
            setPageTitle(this.shortTitle(title,16));
            let cover = this.image(x.coverUrl || x.cover || x.image || x.picUrl);
            let isDrama = type == 'drama' || Array.isArray(x.episodes);
            let meta = [];
            if (isDrama) {
                let epn = x.episodeCount != null ? x.episodeCount : (x.episodes || []).length;
                if (epn) meta.push(epn + '集');
                if (x.heatCount != null) meta.push('🔥' + this.compactNum(x.heatCount));
            } else {
                if (x.categoryName) meta.push(this.cleanText(x.categoryName));
                let du = this.fmtDuration(x.durationSec);
                if (du) meta.push(du);
                if (x.viewCount != null) meta.push('👀' + this.compactNum(x.viewCount));
            }
            if (x.authorName) meta.push(this.cleanText(x.authorName));
            if (x.publishedAt) meta.push(this.fmtDate(x.publishedAt).slice(0,10));

            let localInfo={id:String(id),type:isDrama?'drama':'video',title:title,cover:cover,desc:meta.join(' · ')};
            this.saveHistory(localInfo);

            // 详情顶部改成“封面 + 普通字号标题 + 元数据”，避免长标题被 movie_1 放大后覆盖导航栏。
            if(cover){
                d.push({
                    pic_url:cover,img:cover,
