                col_type:'scroll_button',extra:{backgroundColor:favNow?'#207C6CFF':'#0A777785',lineVisible:false}
            });

            let intro = this.cleanText(x.description || x.intro || x.summary || '');
            if (intro) {
                d.push({
                    title:'““””<b><span style="color:#7C6CFF">▌ 简介</span></b>',
                    url:'hiker://empty', col_type:'text_1', extra:{lineVisible:false}
                });
                // long_text 的正文应写在 title；旧版写在 desc 导致截图里只剩“简介”而内容空白
                d.push({title:intro, url:'hiker://empty', col_type:'long_text', extra:{lineVisible:false}});
            }

            let eps = Array.isArray(x.episodes) ? x.episodes.slice() : [];
            if (eps.length) {
                let reverse = getItem('mdai_episode_reverse','0') == '1';
                if (reverse) eps.reverse();
                let total = eps.length;
                let rangeSize = parseInt(getItem('mdai_episode_range','30')) || 30;
                if (rangeSize < 20) rangeSize = 20;
                if (rangeSize > 50) rangeSize = 50;
                let rangeCount = Math.ceil(total / rangeSize);
                let rk = 'mdai_ep_range_' + id;
                let selected = parseInt(getMyVar(rk, '0')) || 0;
                if (selected < 0 || selected >= rangeCount) selected = 0;

