        var saved = getItem(this.HOST_KEY, "");
        if (saved && this.tryUrl(saved + "/")) return saved;
        var cands = [];
        var push = function(u) {
            u = String(u || "").replace(/\/$/, "");
            if (u && u.indexOf("http") === 0 && cands.indexOf(u) < 0) cands.push(u);
        };
        for (var i = 0; i < this.PUB_PAGES.length; i++) {
            try {
                var base = this.PUB_PAGES[i].replace(/\/$/, "");
                if (/pages\.dev|github\.io/.test(base)) {
                    var js = String(fetch(base + "/publish.js", { timeout: 8000, headers: this.headers() }));
                    var jump = (js.match(/JumpPage="([^"]+)"/) || ["", ""])[1];
                    push(jump);
                    var um = js.match(/var urls=\[([\s\S]*?)\]/);
                    if (um) {
                        var doms = um[1].match(/'([^']+)'/g) || [];
                        for (var d = 0; d < doms.length; d++) {
                            var dom = doms[d].replace(/['" ]/g, "").replace(/\/$/, "");
                            if (dom) push("https://" + dom);
                        }
                    }
                } else {
                    var h = String(fetch(base + "/", { timeout: 8000, headers: this.headers() }));
                    var ms = h.match(/class="ap-url" href="([^"]+)"/g) || [];
                    for (var j = 0; j < ms.length; j++) {
                        push((ms[j].match(/href="([^"]+)"/) || ["", ""])[1]);
                    }
                }
            } catch (e) {}
            if (cands.length >= 8) break;
        }
        var all = cands.concat(this.HOSTS);
        for (var k = 0; k < all.length; k++) {
            var host = String(all[k]).replace(/\/$/, "");
            if (this.tryUrl(host + "/")) {
                setItem(this.HOST_KEY, host);
                log("91短剧 换域成功: " + host);
                return host;
            }
        }
        throw new Error("所有线路均不可用，请稍后重试");
    },
    get: function(path) {
        var hosts = [], saved = getItem(this.HOST_KEY, "");
        if (saved) hosts.push(saved);
        for (var s = 0; s < this.HOSTS.length; s++) {
            if (this.HOSTS[s] !== saved) hosts.push(this.HOSTS[s]);
        }
        var lastHtml = null;
        for (var i = 0; i < hosts.length; i++) {
            try {
                var html = String(fetch(hosts[i] + path, { timeout: 12000, headers: this.headers() }));
                if (html && html.length > 1500) {
                    if (hosts[i] !== saved) setItem(this.HOST_KEY, hosts[i]);
                    return html;
                }
                lastHtml = html;
            } catch (e) {}
        }
        var host = this.pickHost();
        return String(fetch(host + path, { timeout: 12000, headers: this.headers() }));
    },
    abs: function(u) {
