    pic: function(u) {
        u = String(u || "");
        if (!u) return "";
        if (/^(data|hiker):/.test(u)) return u;
        return $(u, this.headers()).image(function() {
            var bytes = null;
            try {
                var baos = new java.io.ByteArrayOutputStream();
                var buf = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 8192);
                var len;
                while ((len = input.read(buf)) > 0) baos.write(buf, 0, len);
                bytes = baos.toByteArray();
                var ka = "f5d965df75336270".split("").map(function(c) { return c.charCodeAt(0); });
                var ia = "97b60394abc2fbe1".split("").map(function(c) { return c.charCodeAt(0); });
                var jb = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, ka.length);
                for (var i = 0; i < ka.length; i++) jb[i] = ka[i] > 127 ? ka[i] - 256 : ka[i];
                var jv = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, ia.length);
                for (var j = 0; j < ia.length; j++) jv[j] = ia[j] > 127 ? ia[j] - 256 : ia[j];
                var cipher = javax.crypto.Cipher.getInstance("AES/CBC/PKCS5Padding");
                cipher.init(javax.crypto.Cipher.DECRYPT_MODE,
                    new javax.crypto.spec.SecretKeySpec(jb, "AES"),
                    new javax.crypto.spec.IvParameterSpec(jv));
                return new java.io.ByteArrayInputStream(cipher.doFinal(bytes));
            } catch (e) {
                if (bytes) { try { return new java.io.ByteArrayInputStream(bytes); } catch (e2) {} }
                return new java.io.ByteArrayInputStream(java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 0));
            }
        });
