        if (gc.length) feedCid = String(gc[0].id);
      } catch (e3) {}
    }
    if (!feedCid) {
      setResult([]);
    } else {
      var lj2 = wgcgPost("video/v2/list", {
        page: page, page_size: PAGE, category_id: parseInt(feedCid, 10) || feedCid
      });
      var rows2 = wgcgRows(lj2);
      log("wgcg home feed page=" + page + " n=" + rows2.length);
      for (var x = 0; x < rows2.length; x++) wgcgPushCard(d, rows2[x]);
      setResult(rows2.length === 0 ? [] : d);
    }
  }
}

