function emojiFlag(countryCode) {
  countryCode = countryCode.toUpperCase();
  let emoji = "";
  for (let i = 0; i < countryCode.length; i++) {
    let code = countryCode.charCodeAt(i) - 65 + 0x1F1E6;
    emoji += String.fromCodePoint(code);
  }
  return emoji;
}

