// ============================================================
// 新吾爱吃瓜网 - 公共模块 (path: common)
// 通过 $.exports 导出, 使用处: var mod = $.require('common');
// ============================================================
var M = {};

M.UA = 'Mozilla/5.0 (Linux; Android 14; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36';
M.REFERER = 'https://5ichiguawang.com/';
M.SITE = 'https://5ichiguawang.com';
M.CDN = 'https://d32bg2g0w9aqg4.cloudfront.net';
M.BAD = ['https://wwkms.tjacq.com', 'http://wwkms.tjacq.com', '//wwkms.tjacq.com'];

// ---------- CDN 域名替换(死链 ww.kms -> 可用 cloudfront) ----------
M.fixCdn = function (url) {
    var u = String(url || '');
    if (!u) return '';
    u = u.split('https://wwkms.tjacq.com').join(M.CDN);
    u = u.split('http://wwkms.tjacq.com').join(M.CDN);
    u = u.split('//wwkms.tjacq.com').join('//d32bg2g0w9aqg4.cloudfront.net');
    return u;
};

// ---------- base64 -> 二进制串(纯 JS,不依赖 atob) ----------
M.b64ToBin = function (b64) {
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var out = [];
    var s = String(b64).replace(/\s+/g, '').replace(/=+$/, '');
    for (var i = 0; i < s.length; i += 4) {
        var g = s.substr(i, 4), n = 0;
        for (var j = 0; j < g.length; j++) n = (n << 6) | chars.indexOf(g.charAt(j));
        var bits = g.length * 6;
        while (bits >= 8) { bits -= 8; out.push(String.fromCharCode((n >> bits) & 255)); }
    }
    return out.join('');
};

// ---------- 图片解密 ----------
// 站点图片有两种形态:
//  1) 标准 JPEG/PNG/GIF/WEBP 二进制 -> 按魔数直接透传
//  2) 源站 text/base64.jpg 形态 -> base64 文本解码为二进制
// 其余未知形态原样返回,不破坏显示
M.decryptImage = function (data) {
    try {
        var s = String(data);
        if (!s) return data;
        var c0 = s.charCodeAt(0);
        if (c0 === 0xFF && s.charCodeAt(1) === 0xD8) return s;                 // JPEG
        if (c0 === 0x89 && s.substr(1, 3) === 'PNG') return s;                // PNG
        var h6 = s.substr(0, 6);
        if (h6 === 'GIF87a' || h6 === 'GIF89a') return s;                     // GIF
        if (s.substr(0, 4) === 'RIFF' && s.substr(8, 4) === 'WEBP') return s; // WEBP
        var t = s.replace(/\s+/g, '');
        if (t.length >= 64 && t.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(t)) {
            return M.b64ToBin(t);
        }
    } catch (e) {}
    return data;
};

// ---------- 图片解密链接: $(url,headers).image(fn, s1, ...) ----------
// 生成格式: url@headers={}@js=(function(){})()
// 解密函数自包含: 内部 $.require('common') 取解密器,失败则原样返回
