// 注意: movie_2 卡片的 title/desc 不解析 HTML,这里只用纯文本+emoji
// 输入 post-card-info 的 HTML 片段，输出如：吃瓜 · 📅2026-09-27 · #今日吃瓜 #网红黑料
M.fmtInfo = function (infoHtml) {
    var h = String(infoHtml || '');
    var author = '', date = '', tags = [];
    var am = h.match(/itemprop="author"[^>]*>([\s\S]*?)<\/span>/);
    if (am) author = am[1].replace(/<[^>]+>/g, '').replace(/[•·\s]+/g, '').trim();
    var dm = h.match(/itemprop="datePublished"[^>]*content="([^"]+)"/);
    if (dm) date = dm[1];
    else {
        var dm2 = h.match(/itemprop="datePublished"[^>]*>([\s\S]*?)<\/span>/);
        if (dm2) date = dm2[1].replace(/<[^>]+>/g, '').trim();
    }
    date = date.replace(/(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日/, function (m, y, mo, d) {
        return y + '-' + ('0' + mo).slice(-2) + '-' + ('0' + d).slice(-2);
    }).replace(/\s+/g, '');
    var sre = /<span(?![^>]*itemprop)[^>]*>([^<]*)<\/span>/g, sm, tlist = [];
    while ((sm = sre.exec(h)) !== null) {
        var tx = sm[1].trim();
        if (tx) tlist.push(tx);
    }
    tags = tlist.join(',').split(/[，,、\s]+/).filter(function (x) { return !!x; });
    var parts = [];
    if (author) parts.push(author);
    if (date) parts.push('📅' + date);
    var desc = parts.join(' · ');
    if (tags.length) desc += (desc ? ' · ' : '') + '#' + tags.join(' #');
    return desc;
