// ---------- 提取元信息(作者/时间/标签) ----------
M.extractMeta = function (html) {
    var h = String(html || '');
    var meta = { author: '', time: '', tags: [] };
    var pm = h.match(/class="post-meta"[^>]*>([\s\S]*?)<\/div>/);
    var seg = pm ? pm[1] : '';
    var am = seg.match(/<span>([^<]{1,20})<\/span>/);
    if (am) meta.author = am[1].trim();
    var tm = seg.match(/<time>([^<]+)<\/time>/);
    if (tm) meta.time = tm[1].trim().replace(/\s+/g, ' ');
    if (!meta.time) {
        var dm = h.match(/itemprop="datePublished"[^>]*content="([^"]+)"/);
        if (dm) meta.time = dm[1].slice(0, 10);
    }
    // 日期归一化: "2026 年 10 月 01 日" -> "2026-10-01"(与列表一致)
    meta.time = meta.time.replace(/(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日/, function (m, y, mo, d) {
        return y + '-' + ('0' + mo).slice(-2) + '-' + ('0' + d).slice(-2);
    }).replace(/\s+/g, '');
    var tagRe = /class="itags"[^>]*>([^<]+)</g;
    var tagM;
    while ((tagM = tagRe.exec(seg)) !== null) {
